class Solution {
public:
    int networkDelayTime(vector<vector<int>>& times, int n, int k) {
        vector<vector<pair<int, int>>> adj(n + 1);
        for (auto& t : times) {
            adj[t[0]].push_back({t[2], t[1]});
        }
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        vector<int> dist(n + 1, -1);
        pq.push({0, k});
        int count = 0, maxDist = 0;
        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (dist[u] != -1) continue;
            dist[u] = d;
            ++count;
            maxDist = max(maxDist, d);
            for (auto& [w, v] : adj[u]) {
                if (dist[v] == -1) {
                    pq.push({d + w, v});
                }
            }
        }
        return count == n ? maxDist : -1;
    }
};

class Solution {
    public int networkDelayTime(int[][] times, int n, int k) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] t : times) adj.get(t[0]).add(new int[]{t[2], t[1]});
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.add(new int[]{0, k});
        int[] dist = new int[n + 1];
        Arrays.fill(dist, -1);
        int count = 0, maxDist = 0;
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1];
            if (dist[u] != -1) continue;
            dist[u] = d;
            count++;
            maxDist = Math.max(maxDist, d);
            for (int[] edge : adj.get(u)) {
                int w = edge[0], v = edge[1];
                if (dist[v] == -1) pq.add(new int[]{d + w, v});
            }
        }
        return count == n ? maxDist : -1;
    }
}

var networkDelayTime = function(times, n, k) {
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v, w] of times) adj[u].push([w, v]);
    const dist = new Array(n + 1).fill(-1);
    const pq = [[0, k]];
    let count = 0, maxDist = 0;
    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, u] = pq.shift();
        if (dist[u] !== -1) continue;
        dist[u] = d;
        count++;
        maxDist = Math.max(maxDist, d);
        for (const [w, v] of adj[u]) {
            if (dist[v] === -1) pq.push([d + w, v]);
        }
    }
    return count === n ? maxDist : -1;
};
